function nominal(){return planningMode?current():scenarios[0];}
function current(){return scenarios.find(s=>s.id===selectedId);}
function activeMap(){return selectedId===nominal()?.id?map:peerMaps.get(selectedId)?.map||map;}
function activeDraft(){return selectedId===nominal()?.id?draft:peerMaps.get(selectedId)?.annotations||draft;}
function activeSketch(){return selectedId===nominal()?.id?sketch:peerMaps.get(selectedId)?.sketch||sketch;}
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
async function api(path,body){if(path==='/api/fire-workspace'&&query.has('case'))path+='?case='+encodeURIComponent(query.get('case'));const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Hazardia-Research':'1'}:{},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.code==='OUTSIDE_COVERAGE'?'Fuori copertura del terreno del simulatore. Premi Mostra area simulabile e verifica inneschi e interventi.':(v.code||r.status)+': '+v.detail);return v;}
function frameAt(r,h){return frameBlend(r,h)?.sample;}
function resultHours(r){return r?Number(r.options?.duration_s/3600||r.frames.at(-1)?.hour||0):0;}
function timeLabel(h){const minutes=Math.round(h*60);return '+'+Math.floor(minutes/60)+' h'+(minutes%60?' '+minutes%60+' min':'');}
function defaultInput(){return {ignitions:[],hours:72,seed:1729,moisture_percent:10,resources:[],weather_source:'FORECAST',weather_changes:[],moisture_model:'HFFMC_1977'};}
