function result(s){return (s.job_id?seriesCache.get(s.job_id):null)||(s.previous_job_id?seriesCache.get(s.previous_job_id):null);}
const visualRasters=new Map(),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)'),uiKey='hazardia-fire-view-v1:'+(query.get('case')||'main');
function storeView(){if(!uiReady)return;try{sessionStorage.setItem(uiKey,JSON.stringify({version:1,hour,selectedId,compared:[...comparison],queue:runQueue,batchIds,batchActive:runningQueue,resume:resumeAfterCalculation,resumeFromHour,frozen:batchFrozen,start:batchStartAt,field:batchForecastId,signatures:Object.fromEntries(scenarios.map(s=>[s.id,signature(s.input)]))}));}catch(e){console.warn('Vista locale non salvata',e);}}
function restoreView(){try{const v=JSON.parse(sessionStorage.getItem(uiKey));if(v?.version!==1||!Number.isFinite(v.hour)||v.hour<0||v.hour>72||!scenarios.every(s=>sameValue(JSON.parse(v.signatures?.[s.id]||'null'),JSON.parse(signature(s.input)))))return;const ids=new Set(scenarios.map(s=>s.id));hour=v.hour;selectedId=ids.has(v.selectedId)?v.selectedId:selectedId;comparison=new Set((v.compared||[]).filter(id=>ids.has(id)));if(v.batchActive&&Number.isFinite(v.resumeFromHour)){runQueue=(v.queue||[]).filter(id=>ids.has(id)&&!scenarios.find(s=>s.id===id).pending);batchIds=(v.batchIds||[]).filter(id=>ids.has(id));runningQueue=true;resumeAfterCalculation=!!v.resume;resumeFromHour=v.resumeFromHour;batchFrozen=!!v.frozen;batchStartAt=v.start;batchForecastId=v.field;}}catch(e){console.warn('Ripristino vista ignorato',e);}}
function nativeStep(){const r=result(current());return r?.frames?.length>1?((r.frames[1].elapsed_s??r.frames[1].hour*3600)-(r.frames[0].elapsed_s??r.frames[0].hour*3600))/3600:.25;}
