function paintVisual(h,weather=false){hour=h;territory.time(h);for(const s of comparedScenarios()){const group=s.id===nominal()?.id?rasters:peerMaps.get(s.id)?.rasters;visualRasters.get(group)?.paint(h,opacity);const m=s.id===nominal()?.id?map:peerMaps.get(s.id)?.map;if(m)weatherLayers.animate(m,scenarioTime(s),weather);}paintedHour=h;$('hour').value=h;$('hour-label').textContent=timeLabel(h);$('play').dataset.renderedHour=String(h);if(weather)$('weather-time').textContent=clock(scenarioTime(current()))+' Roma · '+timeLabel(h)+' · transizione visuale';}
