function pointForecast(field){const p=current()?.input.ignitions[0]?.point||[map.getCenter().lat,map.getCenter().lng],records=[];for(const r of field.records){const v=sampleVector(field,r,...p);if(!v)return null;records.push({at:r.at,values:{wind_speed_10m:Math.hypot(...v),wind_direction_10m:(Math.atan2(-v[0],-v[1])*180/Math.PI+360)%360,temperature_2m:sampleScalar(field,r,'temperature',...p),relative_humidity_2m:sampleScalar(field,r,'humidity',...p),precipitation:sampleScalar(field,r,'precipitation',...p),surface_pressure:sampleScalar(field,r,'pressure',...p),shortwave_radiation:sampleScalar(field,r,'radiation',...p)}});}return {...field,records};}
