function comparisonClock(){return [...new Set(scenarios.filter(s=>s.input.ignitions.length).flatMap(s=>[...s.input.resources,...s.input.ignitions].map(i=>Math.floor(i.at_minutes*60))))].sort((a,b)=>a-b);}
function branchSource(s){const i=s.input;return [result(s),...scenarios.map(result)].find(r=>r&&i.weather_source==='FORECAST'&&Date.parse(i.start_at)===Date.parse(r.valid_from)&&i.hours===resultHours(r)&&i.seed===r.options.seed&&(i.realizations||2)===r.options.realizations&&(i.antecedent_hours||0)===(r.plan.forcing?.initialization?.hours||0)&&i.moisture_percent===r.plan.moisture_percent&&(i.moisture_model||'HFFMC_1977')===(r.plan.forcing?.moisture_model||'HFFMC_1977')&&sameValue(i.ignitions,r.plan.ignitions_wgs84)&&sameValue(i.weather_changes,r.plan.weather_changes));}
