$('run-all').onclick=()=>startComparison(true);
async function startComparison(resume,group=comparedScenarios()){if(runningQueue||scenarios.some(s=>s.pending))return;group=group.filter(s=>s.input.ignitions.length);if(!group.length)return message('Inserisci almeno un innesco nello scenario prima del calcolo.',true);pause();resumeAfterCalculation=resume;resumeFromHour=hour;batchIds=group.map(s=>s.id);batchFrozen=group.every(s=>branchSource(s));let start=current()?.input.start_at;if(!batchFrozen&&(!start||Date.parse(start)<=Date.now()))start=new Date(Math.ceil((Date.now()+1000)/3600000)*3600000).toISOString().replace('.000Z','Z');for(const s of group)if(s.input.weather_source==='FORECAST')s.input.start_at=start;const clock=comparisonClock();const normalize=(s,times)=>[...new Set([...times,...Array.from({length:s.input.hours},(_,h)=>h*3600)])].filter(t=>t<s.input.hours*3600).sort((a,b)=>a-b);const needed=group.filter(s=>dirty(s)||!sameValue(normalize(s,result(s)?.consumed_events.map(e=>e.time)||[]),normalize(s,clock)));batchIds=needed.map(s=>s.id);runQueue=[...batchIds];batchForecastId=null;batchStartAt=start;runningQueue=true;loadControls();scheduleSave();controls();calculationFeedback();await advanceQueue();}
async function advanceQueue(){if(!runningQueue||queueSubmitting||scenarios.some(s=>s.pending))return;if(!runQueue.length){runningQueue=false;controls();const resume=resumeAfterCalculation;resumeAfterCalculation=false;storeView();calculationFeedback();if(resume&&playableScenarios().every(s=>!dirty(s))){hour=Math.min(resumeFromHour,Number($('hour').max));await renderTimeline();if(hour<Number($('hour').max))play();else message('Ricalcolo terminato alla fine dell’orizzonte. Torna indietro per riprodurre i risultati.');}return;}const id=runQueue.shift(),s=scenarios.find(s=>s.id===id);if(!s){runQueue=[];runningQueue=false;controls();message('Uno scenario del confronto è stato rimosso: seleziona il gruppo da ricalcolare.',true);return;}queueSubmitting=true;try{await run(s);}catch(e){s.error=e.message;runQueue=[];runningQueue=false;resumeAfterCalculation=false;render();message(e.message,true);}finally{queueSubmitting=false;storeView();}}
async function poll(){if(polling)return;polling=true;try{for(const s of scenarios.filter(s=>s.pending)){if(s.preparation_id){const preparation=await api('/api/fire-preparations/'+s.preparation_id);s.preparation_detail=preparation.detail;if(preparation.state==='SUCCEEDED'){if(s.job_id&&seriesCache.has(s.job_id))s.previous_job_id=s.job_id;s.job_id=preparation.jobs.B;delete s.preparation_id;delete s.preparation_detail;if(runningQueue&&!batchForecastId)batchForecastId=preparation.forcing_id;scheduleSave();render();}else if(['ERROR','CANCELLED'].includes(preparation.state)){s.pending=false;s.error=preparation.detail;resumeAfterCalculation=false;runQueue=[];runningQueue=false;delete s.preparation_id;scheduleSave();render();message(s.name+': '+s.error,true);continue;}else{render();continue;}}const v=await api('/api/firelab/'+s.job_id);s.progress=v.progress;if(v.state==='SUCCEEDED'){seriesCache.set(s.job_id,v.series);s.pending=false;s.error=null;scheduleSave();render();message(s.name+': risultato disponibile. Usa ▶ Riproduci o sposta il cursore.');}else if(['ERROR','CANCELLED','TIMEOUT'].includes(v.state)){s.pending=false;s.error=v.error_code||v.state;resumeAfterCalculation=false;runQueue=[];runningQueue=false;scheduleSave();render();message(s.name+': '+s.error+'. Gli altri scenari restano disponibili.',true);}}controls();calculationFeedback();await advanceQueue();}catch(e){console.warn('Verifica calcoli scenari',e);message('Verifica calcoli temporaneamente non disponibile. I job restano identificati; riprovo.',true);}finally{polling=false;}}
function inputFromSeries(r){const p=r.plan;return {ignitions:clone(p.ignitions_wgs84||[{id:uid('fire'),point:p.ignition_wgs84,at_minutes:0}]),hours:resultHours(r),seed:r.options?.seed??1729,moisture_percent:p.moisture_percent,...(p.forcing?{moisture_model:p.forcing.moisture_model}:{}),realizations:r.options?.realizations||2,antecedent_hours:p.forcing?.initialization?.hours||0,resources:clone(p.resources),weather_source:p.weather_source,weather_changes:clone(p.weather_changes),...(p.weather_source==='FORECAST'?{start_at:r.valid_from}:{} )};}
function showCase(info){if(!info)return;const banner=document.createElement('aside');banner.className='case-banner';banner.setAttribute('aria-label','Prova salvata separata');const title=document.createElement('strong'),description=document.createElement('p'),back=document.createElement('a');title.textContent=info.title;description.textContent=info.description+' Le modifiche restano separate dai tuoi scenari.';back.textContent='Torna ai miei scenari';back.href='/?view=results';back.target='_top';const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Prova ipotetica · '+info.title;details.append(summary,description,back);banner.append(details);board.prepend(banner);}
async function caseLibrary(){try{const value=await api('/api/fire-cases');if(!value.cases?.length)return;const section=document.createElement('div'),title=document.createElement('strong');title.textContent='Prove salvate · apri senza sostituire i tuoi scenari';section.append(title);for(const c of value.cases){const p=document.createElement('p'),link=document.createElement('a');link.textContent=c.title;link.href='/?view=results&case='+encodeURIComponent(c.id);link.target='_top';p.append(link);section.append(p);}document.querySelector('.workflow-guide').append(section);}catch(e){console.warn('Catalogo prove non disponibile',e);}}
async function init(){try{const saved=await api('/api/fire-workspace'),needsInitialSave=!saved.scenarios.length;showCase(saved.case);void caseLibrary();revision=saved.revision;scenarios=saved.scenarios;$('save-status').textContent=saved.scenarios.length?'Configurazioni salvate nella VM':'';for(const s of scenarios){comparison.add(s.id);if(s.preparation_id)s.pending=true;if(s.previous_job_id){try{const v=await api('/api/firelab/'+s.previous_job_id);if(v.state==='SUCCEEDED')seriesCache.set(s.previous_job_id,v.series);}catch(e){}}if(s.job_id){try{const v=await api('/api/firelab/'+s.job_id);s.progress=v.progress;if(v.state==='SUCCEEDED')seriesCache.set(s.job_id,v.series);else if(!s.preparation_id){s.pending=!['ERROR','CANCELLED','TIMEOUT'].includes(v.state);if(!s.pending)s.error=v.error_code||v.state;}}catch(e){s.error=e.message;}}}if(saved.case)hour=saved.case.initial_hour||0;if(!scenarios.length)newScenario('Scenario nominale',defaultInput());selectedId=scenarios[0].id;restoreView();uiReady=true;planning.initialize();loadControls();render();$('fit').click();await refresh();if(needsInitialSave)scheduleSave();await poll();}catch(e){message('Caricamento configurazioni non riuscito: '+e.message,true);}}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.parent&&e.data?.type==='hazardia-studio-visible')map.invalidateSize({pan:false});});
if(window.parent!==window){let lastHeight=0;new ResizeObserver(()=>{const height=Math.ceil(document.body.getBoundingClientRect().height);if(height!==lastHeight){lastHeight=height;window.parent.postMessage({type:'hazardia-studio-height',height},location.origin);}}).observe(document.body);}
init();setInterval(refresh,30000);setInterval(poll,1500);
